const enc=s=>new TextEncoder().encode(s);
export function imagesPDF(images){const chunks=[enc('%PDF-1.4\n')],offsets=[0];let size=chunks[0].length;const add=x=>{chunks.push(x);size+=x.length;},object=(id,data)=>{offsets[id]=size;add(enc(id+' 0 obj\n'));for(const chunk of Array.isArray(data)?data:[enc(data)])add(chunk);add(enc('\nendobj\n'));};object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,`<< /Type /Pages /Count ${images.length} /Kids [${images.map((_,i)=>(3+i*3)+' 0 R').join(' ')}] >>`);images.forEach((im,i)=>{const id=3+i*3,content=`q 595 0 0 842 0 0 cm /Im${i} Do Q`,jpg=Uint8Array.from(atob(im.data.split(',')[1]),c=>c.charCodeAt(0));object(id,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im${i} ${id+1} 0 R >> >> /Contents ${id+2} 0 R >>`);object(id+1,[enc(`<< /Type /XObject /Subtype /Image /Width ${im.width} /Height ${im.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`),jpg,enc('\nendstream')]);object(id+2,`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);});const start=size;add(enc(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`));for(let i=1;i<offsets.length;i++)add(enc(String(offsets[i]).padStart(10,'0')+' 00000 n \n'));add(enc(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`));return new Blob(chunks,{type:'application/pdf'});}
export async function projectPDF(p,scene){const images=[];let c,ctx,page=0;function start(title){c=document.createElement('canvas');c.width=1240;c.height=1754;ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#283225';ctx.font='bold 32px Arial';ctx.fillText('BATESTO / '+title,65,80);ctx.font='22px Arial';ctx.fillText(p.name.slice(0,70),65,120);ctx.fillStyle='#66745d';ctx.font='17px Arial';ctx.fillText('Предварительный проект · размеры в мм · '+new Date().toLocaleDateString('ru-RU'),65,158);ctx.fillText('Не является картой раскроя или монтажной документацией',65,1690);ctx.fillText(String(++page),1150,1690);ctx.fillStyle='#283225';}function finish(){images.push({data:c.toDataURL('image/jpeg',.92),width:c.width,height:c.height});}const v=roomVertices(p.room),minX=Math.min(...v.map(x=>x.x)),maxX=Math.max(...v.map(x=>x.x)),minZ=Math.min(...v.map(x=>x.z)),maxZ=Math.max(...v.map(x=>x.z));start('План помещения');const k=Math.min(1000/(maxX-minX),1050/(maxZ-minZ)),sx=x=>120+(x-minX)*k,sz=z=>260+(z-minZ)*k;ctx.strokeStyle='#4c6241';ctx.lineWidth=4;ctx.beginPath();v.forEach((p,i)=>i?ctx.lineTo(sx(p.x),sz(p.z)):ctx.moveTo(sx(p.x),sz(p.z)));ctx.closePath();ctx.stroke();ctx.font='18px Arial';for(let i=0;i<v.length;i++){const a=v[i],b=v[(i+1)%v.length];ctx.fillText(`Стена ${i+1}: ${Math.round(Math.hypot(b.x-a.x,b.z-a.z))}`,Math.min(1010,Math.max(65,sx((a.x+b.x)/2)+5)),sz((a.z+b.z)/2)-10);}for(const o of effectiveOpenings(p.room)){const a=v[o.wallIndex],b=v[(o.wallIndex+1)%v.length],len=Math.hypot(b.x-a.x,b.z-a.z);ctx.strokeStyle=o.type==='window'?'#4c96ac':'#b47b3f';ctx.lineWidth=10;ctx.beginPath();for(const [j,t] of [o.offset,o.offset+o.width].entries()){const x=sx(a.x+(b.x-a.x)*t/len),z=sz(a.z+(b.z-a.z)*t/len);j?ctx.lineTo(x,z):ctx.moveTo(x,z);}ctx.stroke();}ctx.strokeStyle='#4c6241';ctx.lineWidth=2;p.modules.forEach((m,i)=>{if(!m.visible)return;ctx.save();ctx.translate(sx(m.x),sz(m.z));ctx.rotate(-m.rotation*Math.PI/180);ctx.fillStyle=m.type==='wall'?'#d8e2cf':'#b8c8a7';ctx.fillRect(-m.width*k/2,-m.depth*k/2,m.width*k,m.depth*k);ctx.strokeRect(-m.width*k/2,-m.depth*k/2,m.width*k,m.depth*k);ctx.restore();});p.modules.forEach((m,i)=>{if(!m.visible)return;ctx.fillStyle='#273323';ctx.fillText(String(i+1),sx(m.x)-5,sz(m.z)+(m.type==='wall'?-5:14));});finish();
for(let wall=0;wall<v.length;wall++){const a=v[wall],b=v[(wall+1)%v.length],length=Math.hypot(b.x-a.x,b.z-a.z),dx=(b.x-a.x)/length,dz=(b.z-a.z)/length;start('Развёртка стены '+(wall+1));const scale=Math.min(1080/length,1100/p.room.height),x=80,y=1450;ctx.strokeRect(x,y-p.room.height*scale,length*scale,p.room.height*scale);for(const o of effectiveOpenings(p.room).filter(o=>o.wallIndex===wall)){ctx.fillStyle=o.type==='window'?'#dcebf0':'#eee5d9';ctx.fillRect(x+o.offset*scale,y-(o.sill+o.height)*scale,o.width*scale,o.height*scale);ctx.strokeRect(x+o.offset*scale,y-(o.sill+o.height)*scale,o.width*scale,o.height*scale);}ctx.fillStyle='#283225';ctx.font='20px Arial';ctx.fillText(`${Math.round(length)} × ${p.room.height} мм`,x,y+40);p.modules.forEach((m,i)=>{if(!m.visible)return;const center=(m.x-a.x)*dx+(m.z-a.z)*dz,dist=Math.abs((m.x-a.x)*dz-(m.z-a.z)*dx),angle=m.rotation*Math.PI/180,span=Math.abs(dx*Math.cos(angle)-dz*Math.sin(angle))*m.width+Math.abs(dx*Math.sin(angle)+dz*Math.cos(angle))*m.depth;if(dist>Math.max(m.depth,m.width)*.75+150||center<0||center>length)return;ctx.fillStyle='#d7e1cd';ctx.fillRect(x+(center-span/2)*scale,y-(m.y+m.height)*scale,span*scale,m.height*scale);ctx.strokeRect(x+(center-span/2)*scale,y-(m.y+m.height)*scale,span*scale,m.height*scale);ctx.fillStyle='#273323';ctx.fillText(`${i+1}: ${m.width}×${m.height}`,x+(center-span/2)*scale+5,y-(m.y+m.height/2)*scale);});ctx.font='18px Arial';ctx.fillText('Показаны модули возле стены; номера соответствуют плану.',80,1550);finish();}
const estimate=estimateProject(p);const rawLines=[...p.modules.flatMap((m,i)=>[`${i+1}. ${m.name} — ${m.width} × ${m.height} × ${m.depth} мм`,`    X ${m.x}; Y ${m.y}; Z ${m.z}; поворот ${m.rotation}°; полок ${m.shelves}; секций ${m.sections}`,`    фасад ${FINISHES[m.front]?.name}; корпус ${FINISHES[m.body]?.name}; ручки ${HANDLES[m.handle]}; механизм ${{hinge:'петли',lift:'подъёмный',slide:'раздвижной',drop:'откидной'}[m.mechanism]}`,`    индивидуально изменено деталей: ${Object.keys(m.details||{}).length}`]),'', 'СМЕТА: геометрическая оценка без отходов раскроя и доставки',...estimate.items.map(i=>`${i.module} / ${i.name} / ${i.sku||'без артикула'}: ${i.quantity.toFixed(2)} ${{m2:'м²',m:'пог. м',piece:'шт.',module:'мод.'}[i.unit]} × ${i.rate??'нет цены'} = ${i.total??'не рассчитано'} ₽`),`Учтённая сумма: ${estimate.subtotal.toLocaleString('ru-RU')} ₽`,...(estimate.missing.length?['Расчёт неполный. Не заполнено:',...estimate.missing]:['Все выбранные позиции оценены. Итог подтверждает мастер.'])];const lines=rawLines.flatMap(line=>{const words=line.split(' '),rows=[];let row='';for(const word of words){if((row+' '+word).length>98){rows.push(row);row=word;}else row+=(row?' ':'')+word;}rows.push(row);return rows;});for(let offset=0;offset<lines.length;offset+=48){start('Спецификация и расчёт');ctx.font='19px Arial';lines.slice(offset,offset+48).forEach((line,i)=>ctx.fillText(line.slice(0,115),65,220+i*28));finish();}return imagesPDF(images);}
